import {Table} from './table';
import {TableHeader} from './table-header';
import {TableBody} from './table-body';
import {SizeGate} from '../../ui/size-gate';
const frame=()=>new Promise<void>(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r())));
const check=(ok:boolean,message:string)=>{if(!ok)throw new Error(message);};
type Row=Identifiable<{}>;
function model():Table.ViewModel<Row>{return Table.ViewModel.makeDefault({columns:[{id:'value',label:'Value',make:()=>document.createElement('span'),bind:(e,item)=>{e.textContent=String(item.id);},sortComparator:(a,b)=>String(a.id).localeCompare(String(b.id))}]});}
export async function verifyHeaderLifetime():Promise<string[]>{
 const a=model(),t=Table.makeTyped<Row>();t.style.width='800px';t.style.height='300px';t.bind(a);document.body.append(t);await frame();t.bindItems([{id:'one'},{id:'two'}]);await t.itemsReadyPromise;await frame();
 const h=t.shadowRoot!.querySelector<TableHeader<Row>>('std-table-header')!;const col=h.shadowRoot!.querySelector<TableHeader.Column<Row>>('std-table-header-column')!;
 const body=t.shadowRoot!.querySelector<TableBody<Row>>('std-table-body')!;
 const counts=()=>({layout:Reflect.get(a.layoutInvalidated,'listeners').size,sort:Reflect.get(a.sortState,'listeners').size});const start=counts();
 for(let i=0;i<5;i++){t.remove();document.body.append(t);await frame();a.updateStyle({containerMarginInline:31+i,cellPadding:14+i});await frame();check(h.style.getPropertyValue('--container-margin-inline')===`${31+i}px`,'Header reconnect spacing');check(t.shadowRoot!.querySelector<HTMLElement>('std-table-body')!.style.getPropertyValue('--container-margin-inline')===`${31+i}px`,'Body reconnect spacing');check(col.style.getPropertyValue('--cell-padding')===`${14+i}px`,'Column current padding');for(const sort of ['ascending','descending',null]){a.toggleSort('value');await frame();check(col.getAttribute('aria-sort')===sort,'Column reconnect sort '+sort);}check(JSON.stringify(counts())===JSON.stringify(start),'Duplicate reconnect subscriptions');}
 t.recycle();await frame();check(Reflect.get(a.layoutInvalidated,'listeners').size===0&&Reflect.get(a.sortState,'listeners').size===0,'Retired Table children retained model listeners');
 const gate=new SizeGate();gate.resolve({width:800,height:300});const detached=TableHeader.make();void detached.bind(a,gate);detached.recycle();await frame();const b=TableHeader.make();check(b===detached,'Detached header actual reuse');const newer=model();await b.bind(newer,gate);const before=b.style.getPropertyValue('--container-margin-inline');a.updateStyle({containerMarginInline:99});check(b.style.getPropertyValue('--container-margin-inline')===before,'Retired model reached Header successor');b.recycle();await frame();await frame();check(Reflect.get(newer.layoutInvalidated,'listeners').size===0,'Header successor retained listeners');
 const first=TableHeader.Column.make();first.bind(a.orderedColumns[0],a.resolveWidthSpec('value'),a);first.recycle();await frame();const second=TableHeader.Column.make();check(first===second,'Column actual detached reuse');second.bind(newer.orderedColumns[0],newer.resolveWidthSpec('value'),newer);a.toggleSort('value');check(second.getAttribute('aria-sort')===null,'Retired sort model reached successor');newer.toggleSort('value');check(second.getAttribute('aria-sort')==='ascending','Current detached sort stopped');second.recycle();await frame();
 const detachedBody=TableBody.make();detachedBody.bind(a,[{id:'detached'}]);detachedBody.recycle();await frame();const bodySuccessor=TableBody.make();check(bodySuccessor===detachedBody,'Body actual detached reuse');bodySuccessor.bind(newer,[{id:'current'}]);const bodyMargin=bodySuccessor.style.getPropertyValue('--container-margin-inline');a.updateStyle({containerMarginInline:111});check(bodySuccessor.style.getPropertyValue('--container-margin-inline')===bodyMargin,'Retired model reached body successor');bodySuccessor.recycle();await frame();check(Reflect.get(newer.layoutInvalidated,'listeners').size===0,'Retired body retained model listener');
 return ['Header, Body and Column five reconnects restore spacing/asc/desc/cleared sort exactly once','Detached Header/Column direct recycle and actual replacement models exclude retired subscriptions'];
}
